Looking at the implementation and ticket requirements, I need to write a comprehensive pytest suite that tests:

1. **Normal formatting** across different exponent values (0, 2, 3, 4 decimals)
2. **ROUND_HALF_EVEN rounding** behavior
3. **Currency lookup order** (before amount parsing)
4. **Negative amounts and negative zero** handling
5. **Input parsing** (scientific notation, whitespace, various invalid formats)
6. **Output formatting** (zero-padding, no decimal point for exponent=0, no leading +)
7. **Error cases** (KeyError for unknown currency, ValueError for invalid/non-finite amounts)

Let me trace through a couple of critical examples to verify my test expectations:
- `"2.675"` USD: Decimal quantizes to 2.68 (68 is even, so tie rounds there) ✓
- `"1234.5"` JPY: Quantizes to 1234 (4 is even, so 1234.5 rounds to 1234) ✓
- `"-0.004"` USD: Quantizes to -0.00, then converted to unsigned 0.00 ✓
- Currency lookup happens first (test with invalid amount + unknown currency → KeyError) ✓

```json
{"code": "import pytest
import impl


def test_usd_simple_amount():
    """Test formatting a simple USD amount with 2 decimals."""
    exponents = {"USD": 2}
    assert impl.format_amount("1.23", "USD", exponents) == "1.23"


def test_jpy_zero_decimals():
    """Test JPY which has 0 decimal places (no minor units)."""
    exponents = {"JPY": 0}
    assert impl.format_amount("1234.5", "JPY", exponents) == "1234"


def test_kwd_three_decimals():
    """Test KWD with 3 decimal places."""
    exponents = {"KWD": 3}
    assert impl.format_amount("1.234", "KWD", exponents) == "1.234"


def test_rounding_half_even_ties():
    """Test ROUND_HALF_EVEN rounding behavior with tie cases."""
    exponents = {"USD": 2}
    # 2.675 rounds to 2.68 (68 is even)
    assert impl.format_amount("2.675", "USD", exponents) == "2.68"
    # 2.665 rounds to 2.66 (66 is even)
    assert impl.format_amount("2.665", "USD", exponents) == "2.66"


def test_negative_amounts():
    """Test that negative amounts are preserved and round correctly."""
    exponents = {"USD": 2}
    assert impl.format_amount("-2.675", "USD", exponents) == "-2.68"
    assert impl.format_amount("-1.23", "USD", exponents) == "-1.23"


def test_negative_zero_handling():
    """Test that negative zero is converted to unsigned zero."""
    exponents = {"USD": 2, "JPY": 0}
    assert impl.format_amount("-0.004", "USD", exponents) == "0.00"
    assert impl.format_amount("-0.4", "JPY", exponents) == "0"


def test_scientific_notation():
    """Test scientific notation is correctly parsed."""
    exponents = {"USD": 2}
    assert impl.format_amount("1E+2", "USD", exponents) == "100.00"
    assert impl.format_amount("1.5e-3", "USD", exponents) == "0.00"


def test_whitespace_handling():
    """Test that surrounding whitespace is handled."""
    exponents = {"USD": 2}
    assert impl.format_amount(" 1.23 ", "USD", exponents) == "1.23"
    assert impl.format_amount("\t1.00\n", "USD", exponents) == "1.00"


def test_zero_padding():
    """Test that results are zero-padded to correct decimal places."""
    exponents = {"USD": 2, "KWD": 3}
    assert impl.format_amount("1", "USD", exponents) == "1.00"
    assert impl.format_amount("1.1", "USD", exponents) == "1.10"
    assert impl.format_amount("1", "KWD", exponents) == "1.000"


def test_positive_sign_handling():
    """Test that explicit + sign is removed from output."""
    exponents = {"USD": 2}
    assert impl.format_amount("+1.23", "USD", exponents) == "1.23"


def test_large_numbers():
    """Test very large numbers are formatted correctly."""
    exponents = {"USD": 2}
    assert impl.format_amount("999999999999.99", "USD", exponents) == "999999999999.99"
    assert impl.format_amount("1E+10", "USD", exponents) == "10000000000.00"


def test_currency_not_found():
    """Test that unknown currency raises KeyError."""
    exponents = {"USD": 2}
    with pytest.raises(KeyError):
        impl.format_amount("1.23", "EUR", exponents)


def test_currency_lookup_before_amount_validation():
    """Test that currency is looked up before amount is parsed."""
    exponents = {"USD": 2}
    # Should raise KeyError, not ValueError, even though amount is invalid
    with pytest.raises(KeyError):
        impl.format_amount("invalid_amount", "EUR", exponents)


def test_invalid_amounts():
    """Test that various invalid amount formats raise ValueError."""
    exponents = {"USD": 2}
    invalid_amounts = ["", "abc", "1.2.3", "12,34", "$1.00", "1 000.00"]
    for amount in invalid_amounts:
        with pytest.raises(ValueError):
            impl.format_amount(amount, "USD", exponents)


def test_non_finite_values():
    """Test that non-finite values raise ValueError."""
    exponents = {"USD": 2}
    non_finite = ["NaN", "sNaN", "Infinity", "-Infinity"]
    for amount in non_finite:
        with pytest.raises(ValueError):
            impl.format_amount(amount, "USD", exponents)


def test_currency_case_sensitive():
    """Test that currency codes are case-sensitive (exact lookup)."""
    exponents = {"USD": 2}
    with pytest.raises(KeyError):
        impl.format_amount("1.23", "usd", exponents)
    with pytest.raises(KeyError):
        impl.format_amount("1.23", "Usd", exponents)


def test_rounding_and_precision():
    """Test rounding with various input precisions."""
    exponents = {"USD": 2, "KWD": 3}
    # Small amount that rounds to zero
    assert impl.format_amount("0.001", "USD", exponents) == "0.00"
    # Amount within target precision is preserved
    assert impl.format_amount("0.001", "KWD", exponents) == "0.001"
    # Extra decimals are rounded away
    assert impl.format_amount("1.234567", "USD", exponents) == "1.23"


def test_zero_formatting():
    """Test zero formatting in different currencies."""
    exponents = {"USD": 2, "JPY": 0, "KWD": 3}
    assert impl.format_amount("0", "USD", exponents) == "0.00"
    assert impl.format_amount("0", "JPY", exponents) == "0"
    assert impl.format_amount("0", "KWD", exponents) == "0.000""}
